  addOrUpdateProductToList($productRow: JQuery, newRow: HTMLElement): void {
    if ($productRow.length > 0) {
      $productRow.html($(newRow).html());
    } else {
      $(OrderViewPageMap.productAddRow).before(
        $(newRow)
          .hide()
          .fadeIn(),
      );
